[public_service] {
  "normative_requirements": {
    "project_scale_category": "Standard not specified in context",
    "lobby_capacity_guide": "Standard not specified in context",
    "sanitary_facilities": {
      "ratio_requirement": "Standard not specified in context",
      "accessibility_note": "根据《民用建筑设计统一标准》，无障碍厕所隔间（外开门）平面尺寸为1.5m×2.0m（不应小于1.0m×1.8m）。"
    },
    "compliance_source": [
      "博物馆建筑设计规范",
      "民用建筑设计统一标准",
      "无障碍设计规范",
      "建筑设计防火规范",
      "科学技术馆建设标准"
    ]
  },
  "design_strategies": {
    "entrance_lobby": {
      "flow_strategy": {
        "description": "设置专门的接待与导向空间(Reception and orientation space)作为流线起点；同时可利用环绕建筑的步道体系，允许访客在进入大堂前或参观后环绕建筑通行。",
        "case_reference": "Museum of Medical History and Innovation; Museum of Tomorrow",
        "is_general_knowledge": false
      },
      "atmosphere": {
        "description": "打造具有象征意义的中央大厅，利用高挑的中庭（如四层高）、穹顶结构、彩色玻璃及石材墙面，营造古典、庄重且具有历史感的氛围。",
        "case_reference": "National Museum of Nature and Science, Tokyo",
        "is_general_knowledge": false
      }
    },
    "commercial_planning": [
      {
        "zone": "公共服务型餐饮与工坊",
        "location_logic": "将咖啡厅与工坊剥离出博物馆内部服务区，直接面向公众和广场开放，以此连接城市日常动态与项目活动。",
        "case_reference": "Geology Museum",
        "is_general_knowledge": false
      },
      {
        "zone": "非购票区文创与休闲",
        "location_logic": "在非购票公共区域(unticketed public areas)设置博物馆商店与咖啡厅，使其成为服务当地居民的公共空间的一部分。",
        "case_reference": "Biomuseo",
        "is_general_knowledge": false
      },
      {
        "zone": "综合配套设施",
        "location_logic": "在馆内整合餐厅、博物馆商店及礼堂，形成完整的访客服务闭环。",
        "case_reference": "Horno 3 Steel Museum; Museum of Tomorrow",
        "is_general_knowledge": false
      }
    ],
    "amenity_innovation": {
      "description": "前场体验升级策略：通过环绕建筑的广场(Plaza)和公园步道(Park walkway)最大化景观连续性，设置花园与休闲区，将博物馆外部打造为公众可自由进入的城市休闲节点。",
      "case_reference": "Museum of Tomorrow; Biomuseo",
      "is_general_knowledge": false
    }
  }
}
